scenes.code:
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }

body {
     margin: 0;
     padding: 24px 16px;
     font-family: Arial, "Segoe UI", sans-serif;
     background: #eef3f8;
     display: flex;
     justify-content: center;
}

.trang-tin {
     width: min(1040px, 100%);
     background: #ffffff;
     box-shadow: 0 0 26px rgba(0, 0, 0, 0.1);
}

.dau-trang {
     padding: 14px 22px;
     border-bottom: 3px solid #1668C1;
}

.dau-trang h1 {
     margin: 0;
     color: #1668C1;
     font-size: 26px;
}

.khung-chinh {
    display: grid;
    grid-template-columns: 210px 1fr;
}

nav {
    background: #f7fafd;
    border-right: 1px solid #dce6f2;
    padding: 16px;
}

nav h2 {
    font-size: 11px;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: #888888;
    margin: 0 0 8px;
}

nav a {
    display: block;
    color: #1668C1;
    text-decoration: none;
    padding: 6px 0;
    font-size: 14px;
}

nav a:hover { text-decoration: underline; }

main { padding: 18px 22px; }

.chuyen-muc { margin-bottom: 18px; }

.thanh-cm {
    background: #1668C1;
    color: #ffffff;
    padding: 7px 12px;
    border-radius: 3px;

    font-size: 16px;
    margin: 0 0 12px;
}

.bai-nho {
    display: grid;
    grid-template-columns: 1fr 140px;
    gap: 16px;
    align-items: start;
    padding: 12px 0;
    border-bottom: 1px dashed #dce6f2;
}

.bai-nho img {
    width: 100%;
    border-radius: 6px;
    display: block;
}

.bai-nho h3 {
    color: #1668C1;
    font-size: 15px;
    margin: 0 0 6px;
}

.bai-nho p {
    margin: 0;
    font-size: 13.5px;
    line-height: 1.55;
    color: #333333;
}

.ve-dau-trang {
    display: block;
    text-align: right;
    font-size: 12.5px;
    color: #1668C1;
    margin-top: 6px;

     text-decoration: none;
}

@media (max-width: 720px) {
     .khung-chinh { grid-template-columns: 1fr; }
     nav { border-right: none; border-bottom: 1px solid #dce6f2; }
}
